using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using IndianOceanAssets.ShooterSurvival;using Object=UnityEngine.Object;
public static class InspectRoleVisualLayout {public static object Main(string scene){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/"+scene+".unity");var d=Object.FindFirstObjectByType<Chapter45Director>();return new{scene,actors=d.encounters.SelectMany(e=>e.actors).Select(a=>new{a.name,rootScale=a.transform.localScale.ToString(),role=a.GetComponent<Chapter45RoleAction>()?.role.ToString(),children=a.transform.Cast<Transform>().Select(t=>new{t.name,pos=t.localPosition.ToString(),scale=t.localScale.ToString(),components=t.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray(),skins=t.GetComponentsInChildren<SkinnedMeshRenderer>(true).Length,animators=t.GetComponentsInChildren<Animator>(true).Length}).ToArray(),animators=a.GetComponentsInChildren<Animator>(true).Select(x=>AnimationUtility.CalculateTransformPath(x.transform,a.transform)).ToArray(),held=(a.GetComponent<Chapter45RoleAction>() != null && a.GetComponent<Chapter45RoleAction>().heldProp != null ? a.GetComponent<Chapter45RoleAction>().heldProp.name : null)}).ToArray(),life=d.GetComponentsInChildren<Chapter4StreetLife>(true).Take(1).Select(l=>new{l.name,walkers=l.walkers.Take(5).Select(w=>new{name=w.body.name,parent=w.body.parent.name,pos=w.body.localPosition.ToString(),scale=w.body.localScale.ToString(),origin=w.origin.ToString()}).ToArray()}).ToArray(),hazards=d.hazards.Select(h=>new{h.name,body=h.body?.name,scale=h.body?.localScale.ToString(),children=h.body?.Cast<Transform>().Select(t=>new{t.name,pos=t.localPosition.ToString(),scale=t.localScale.ToString()}).ToArray()}).ToArray()};}}
